import React, { Component } from 'react';
import { Link } from 'react-router-dom';
import axios from 'axios';
import MyContext from '../contexts/MyContext';
import './Home.css';

class Home extends Component {
  static contextType = MyContext;

  constructor(props) {
    super(props);
    this.state = {
      customers: [],
      orders: [],
      loading: true
    };
  }

  componentDidMount() {
    this.apiGetDashboardData();
  }

  apiGetDashboardData() {
    const config = { headers: { 'x-access-token': this.context.token } };
    axios
      .all([
        axios.get('/api/admin/customers', config),
        axios.get('/api/admin/orders', config)
      ])
      .then(
        axios.spread((custRes, orderRes) => {
          this.setState({
            customers: custRes.data,
            orders: orderRes.data,
            loading: false
          });
        })
      )
      .catch(() => this.setState({ loading: false }));
  }

  render() {
    return (
      <div className="admin-home">

        <h2 className="admin-title">ADMIN DASHBOARD</h2>

        {/* Dashboard */}
        <div className="dashboard">
          <Link to="/admin/product" className="card card-blue">
            <span>👟 Products</span>
            <div className="card-subtitle">Manage products</div>
          </Link>

          <Link to="/admin/order" className="card card-green">
            <span>📦 Orders</span>
            <div className="card-subtitle">Track orders</div>
          </Link>

          <Link to="/admin/category" className="card card-orange">
            <span>🗂 Categories</span>
            <div className="card-subtitle">Manage categories</div>
          </Link>

          <Link to="/admin/customer" className="card card-red">
            <span>👤 Customers</span>
            <div className="card-subtitle">User management</div>
          </Link>
        </div>

        {/* Welcome Section */}
        <div className="welcome-section">
          <div className="welcome-left">
            <h3 className="welcome-title">Welcome to Admin Panel! 👋</h3>
            <p className="welcome-text">
              Manage your online shopping store efficiently. Monitor all your products, orders, categories, and customers from one centralized dashboard.
            </p>
            <div className="welcome-stats">
              <div className="stat-item">
                <div className="stat-number">1000+</div>
                <div className="stat-label">Products</div>
              </div>
              <div className="stat-item">
                <div className="stat-number">500+</div>
                <div className="stat-label">Orders</div>
              </div>
              <div className="stat-item">
                <div className="stat-number">150+</div>
                <div className="stat-label">Customers</div>
              </div>
            </div>
          </div>
          <div className="welcome-right">
            <svg viewBox="0 0 300 300" className="welcome-svg">
              {/* Background circle */}
              <circle cx="150" cy="150" r="140" fill="#f0f4ff" />

              {/* Shopping bag */}
              <g>
                <rect x="100" y="80" width="100" height="120" rx="10" fill="#3498db" />
                <path d="M 110 80 Q 110 60 130 60 Q 150 55 170 60 Q 190 60 190 80" fill="#2980b9" />
                <line x1="120" y1="110" x2="180" y2="110" stroke="white" strokeWidth="2" />
                <line x1="120" y1="140" x2="180" y2="140" stroke="white" strokeWidth="2" />
              </g>

              {/* Stars */}
              <circle cx="250" cy="80" r="8" fill="#f1c40f" />
              <circle cx="260" cy="100" r="6" fill="#f39c12" />
              <circle cx="50" cy="120" r="7" fill="#e74c3c" />
              <circle cx="270" cy="180" r="5" fill="#9b59b6" />
              <circle cx="40" cy="200" r="6" fill="#1abc9c" />
            </svg>
          </div>
        </div>

      </div>
    );
  }
}

export default Home;
